DROP DATABASE IF EXISTS `muse_erd_core`;
CREATE DATABASE `muse_erd_core` CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE `muse_erd_core`;

CREATE TABLE `users` (
  `user_id` int unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(30) NOT NULL,
  `email` varchar(120) NOT NULL,
  `password_hash` char(60) NOT NULL,
  `password_changed_at` datetime DEFAULT NULL,
  `role_id` tinyint unsigned NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `failed_login_count` tinyint unsigned NOT NULL DEFAULT '0',
  `locked_until` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `last_login_at` datetime DEFAULT NULL,
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `uq_users_username` (`username`),
  UNIQUE KEY `uq_users_email` (`email`),
  KEY `fk_users_role` (`role_id`),
  CONSTRAINT `chk_users_email` CHECK ((`email` like _utf8mb4'%_@_%._%')),
  CONSTRAINT `chk_users_username` CHECK (regexp_like(`username`,_utf8mb4'^[a-z0-9_]{3,30}$',_utf8mb4'c'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `user_profiles` (
  `user_id` int unsigned NOT NULL,
  `display_name` varchar(60) NOT NULL,
  `region_code` varchar(6) DEFAULT NULL,
  `content_filter` enum('OFF','NO_EXPLICIT','FAMILY') NOT NULL DEFAULT 'OFF',
  `listening_habit` enum('BACKGROUND','ACTIVE','MIXED') DEFAULT NULL,
  `onboarding_completed_at` datetime DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`),
  KEY `fk_up_region` (`region_code`),
  CONSTRAINT `fk_up_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `artists` (
  `artist_id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `normalized_name` varchar(100) GENERATED ALWAYS AS (trim(regexp_replace(lower(`name`),_utf8mb4'[!-/:-@\\[-`{-~—–‘’“”[:space:]]+',_utf8mb4' '))) STORED,
  `disambiguation` varchar(80) NOT NULL DEFAULT '',
  `artist_type` enum('SOLO','GROUP','COMPOSER','ORCHESTRA') NOT NULL DEFAULT 'SOLO',
  `country_code` char(2) NOT NULL DEFAULT 'IN',
  `region_code` varchar(6) DEFAULT NULL,
  `primary_language_id` smallint unsigned DEFAULT NULL,
  `formed_year` smallint unsigned DEFAULT NULL,
  `bio` varchar(400) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`artist_id`),
  UNIQUE KEY `uq_artists_identity` (`normalized_name`,`disambiguation`),
  KEY `fk_artists_region` (`region_code`),
  KEY `fk_artists_lang` (`primary_language_id`),
  FULLTEXT KEY `ft_artists_name` (`name`) /*!50100 WITH PARSER `ngram` */ ,
  CONSTRAINT `chk_artists_year` CHECK (((`formed_year` is null) or (`formed_year` between 1900 and 2100)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `albums` (
  `album_id` int unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(150) NOT NULL,
  `normalized_title` varchar(150) GENERATED ALWAYS AS (trim(regexp_replace(lower(`title`),_utf8mb4'[!-/:-@\\[-`{-~—–‘’“”[:space:]]+',_utf8mb4' '))) STORED,
  `album_type` enum('ALBUM','EP','SINGLE','SOUNDTRACK','COMPILATION') NOT NULL DEFAULT 'ALBUM',
  `film_id` int unsigned DEFAULT NULL,
  `release_year` smallint unsigned NOT NULL,
  `language_id` smallint unsigned DEFAULT NULL,
  `cover_color_1` char(7) NOT NULL,
  `cover_color_2` char(7) NOT NULL,
  PRIMARY KEY (`album_id`),
  KEY `idx_albums_normalized` (`normalized_title`),
  KEY `fk_albums_film` (`film_id`),
  KEY `fk_albums_lang` (`language_id`),
  FULLTEXT KEY `ft_albums_title` (`title`) /*!50100 WITH PARSER `ngram` */ ,
  CONSTRAINT `chk_albums_colors` CHECK ((regexp_like(`cover_color_1`,_utf8mb4'^#[0-9A-Fa-f]{6}$') and regexp_like(`cover_color_2`,_utf8mb4'^#[0-9A-Fa-f]{6}$'))),
  CONSTRAINT `chk_albums_film` CHECK (((`film_id` is null) or (`album_type` = _utf8mb4'SOUNDTRACK'))),
  CONSTRAINT `chk_albums_year` CHECK ((`release_year` between 1900 and 2100))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `songs` (
  `song_id` int unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(150) NOT NULL,
  `normalized_title` varchar(150) GENERATED ALWAYS AS (trim(regexp_replace(lower(`title`),_utf8mb4'[!-/:-@\\[-`{-~—–‘’“”[:space:]]+',_utf8mb4' '))) STORED,
  `version_label` varchar(40) NOT NULL DEFAULT '',
  `primary_artist_id` int unsigned NOT NULL,
  `album_id` int unsigned DEFAULT NULL,
  `track_number` tinyint unsigned DEFAULT NULL,
  `duration_sec` smallint unsigned NOT NULL,
  `release_year` smallint unsigned NOT NULL,
  `language_id` smallint unsigned DEFAULT NULL,
  `isrc` char(12) DEFAULT NULL,
  `explicit` tinyint(1) NOT NULL DEFAULT '0',
  `content_rating` enum('ALL','TEEN','MATURE') NOT NULL DEFAULT 'ALL',
  `popularity` tinyint unsigned NOT NULL DEFAULT '50',
  `status` enum('ACTIVE','PENDING_ANALYSIS','HIDDEN','MERGED') NOT NULL DEFAULT 'ACTIVE',
  `merged_into_song_id` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`song_id`),
  UNIQUE KEY `uq_songs_identity` (`primary_artist_id`,`normalized_title`,`version_label`),
  UNIQUE KEY `uq_songs_isrc` (`isrc`),
  KEY `idx_songs_album` (`album_id`,`track_number`),
  KEY `idx_songs_lang_status` (`language_id`,`status`),
  KEY `idx_songs_status_pop` (`status`,`popularity`),
  KEY `fk_songs_merged` (`merged_into_song_id`),
  FULLTEXT KEY `ft_songs_title` (`title`) /*!50100 WITH PARSER `ngram` */ ,
  CONSTRAINT `fk_songs_album` FOREIGN KEY (`album_id`) REFERENCES `albums` (`album_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_songs_artist` FOREIGN KEY (`primary_artist_id`) REFERENCES `artists` (`artist_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_songs_merged` FOREIGN KEY (`merged_into_song_id`) REFERENCES `songs` (`song_id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_songs_duration` CHECK ((`duration_sec` between 30 and 1800)),
  CONSTRAINT `chk_songs_explicit` CHECK (((`explicit` = 0) or (`content_rating` <> _utf8mb4'ALL'))),
  CONSTRAINT `chk_songs_isrc` CHECK (((`isrc` is null) or regexp_like(`isrc`,_utf8mb4'^[A-Z]{2}[A-Z0-9]{3}[0-9]{7}$',_utf8mb4'c'))),
  CONSTRAINT `chk_songs_merge` CHECK (((`status` = _utf8mb4'MERGED') = (`merged_into_song_id` is not null))),
  CONSTRAINT `chk_songs_pop` CHECK ((`popularity` <= 100)),
  CONSTRAINT `chk_songs_year` CHECK ((`release_year` between 1900 and 2100))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `genres` (
  `genre_id` smallint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(40) NOT NULL,
  `parent_genre_id` smallint unsigned DEFAULT NULL,
  `color_hex` char(7) NOT NULL,
  `description` varchar(200) DEFAULT NULL,
  PRIMARY KEY (`genre_id`),
  UNIQUE KEY `uq_genres_name` (`name`),
  KEY `fk_genres_parent` (`parent_genre_id`),
  CONSTRAINT `fk_genres_parent` FOREIGN KEY (`parent_genre_id`) REFERENCES `genres` (`genre_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chk_genres_color` CHECK (regexp_like(`color_hex`,_utf8mb4'^#[0-9A-Fa-f]{6}$'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `song_genres` (
  `song_id` int unsigned NOT NULL,
  `genre_id` smallint unsigned NOT NULL,
  `is_primary` tinyint(1) NOT NULL DEFAULT '0',
  `primary_song_key` int unsigned GENERATED ALWAYS AS (if((`is_primary` = 1),`song_id`,NULL)) VIRTUAL,
  PRIMARY KEY (`song_id`,`genre_id`),
  UNIQUE KEY `uq_sg_one_primary` (`primary_song_key`),
  KEY `idx_sg_genre` (`genre_id`,`is_primary`),
  CONSTRAINT `fk_sg_genre` FOREIGN KEY (`genre_id`) REFERENCES `genres` (`genre_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_sg_song` FOREIGN KEY (`song_id`) REFERENCES `songs` (`song_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `moods` (
  `mood_id` smallint unsigned NOT NULL AUTO_INCREMENT,
  `category_id` tinyint unsigned NOT NULL,
  `name` varchar(30) NOT NULL,
  `emoji` varchar(8) NOT NULL,
  `color_hex` char(7) NOT NULL,
  `description` varchar(200) NOT NULL,
  `target_energy` decimal(4,3) NOT NULL,
  `target_valence` decimal(4,3) NOT NULL,
  `target_danceability` decimal(4,3) NOT NULL,
  `target_acousticness` decimal(4,3) NOT NULL,
  `target_instrumentalness` decimal(4,3) NOT NULL,
  `tempo_min` decimal(5,1) NOT NULL,
  `tempo_max` decimal(5,1) NOT NULL,
  PRIMARY KEY (`mood_id`),
  UNIQUE KEY `uq_moods_name` (`name`),
  KEY `fk_moods_category` (`category_id`),
  CONSTRAINT `chk_moods_color` CHECK (regexp_like(`color_hex`,_utf8mb4'^#[0-9A-Fa-f]{6}$')),
  CONSTRAINT `chk_moods_targets` CHECK (((`target_energy` between 0 and 1) and (`target_valence` between 0 and 1) and (`target_danceability` between 0 and 1) and (`target_acousticness` between 0 and 1) and (`target_instrumentalness` between 0 and 1))),
  CONSTRAINT `chk_moods_tempo` CHECK (((`tempo_min` >= 40) and (`tempo_max` <= 220) and (`tempo_min` < `tempo_max`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `song_moods` (
  `song_id` int unsigned NOT NULL,
  `mood_id` smallint unsigned NOT NULL,
  `model_id` smallint unsigned NOT NULL,
  `confidence` decimal(4,3) NOT NULL,
  `feature_id` int unsigned NOT NULL,
  `analyzed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`song_id`,`mood_id`,`model_id`),
  KEY `idx_sm_model_mood` (`model_id`,`mood_id`,`confidence`),
  KEY `fk_sm_mood` (`mood_id`),
  KEY `fk_sm_feature` (`feature_id`),
  CONSTRAINT `fk_sm_mood` FOREIGN KEY (`mood_id`) REFERENCES `moods` (`mood_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_sm_song` FOREIGN KEY (`song_id`) REFERENCES `songs` (`song_id`) ON DELETE CASCADE,
  CONSTRAINT `chk_sm_conf` CHECK (((`confidence` > 0) and (`confidence` <= 1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `song_mood_ratings` (
  `user_id` int unsigned NOT NULL,
  `song_id` int unsigned NOT NULL,
  `mood_id` smallint unsigned NOT NULL,
  `match_percentage` decimal(5,2) NOT NULL,
  `review_text` varchar(280) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`,`song_id`,`mood_id`),
  KEY `idx_smr_song_mood` (`song_id`,`mood_id`,`match_percentage`),
  KEY `idx_smr_mood_song` (`mood_id`,`song_id`,`match_percentage`),
  CONSTRAINT `fk_smr_mood` FOREIGN KEY (`mood_id`) REFERENCES `moods` (`mood_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_smr_song` FOREIGN KEY (`song_id`) REFERENCES `songs` (`song_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_smr_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `chk_smr_pct` CHECK (((`match_percentage` >= 0) and (`match_percentage` <= 100))),
  CONSTRAINT `chk_smr_review` CHECK (((`review_text` is null) or (char_length(trim(`review_text`)) > 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `listening_sessions` (
  `session_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `context_id` tinyint unsigned DEFAULT NULL,
  `device` varchar(30) NOT NULL DEFAULT 'web',
  `started_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `last_activity_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ended_at` datetime DEFAULT NULL,
  `status` enum('OPEN','CLOSED') NOT NULL DEFAULT 'OPEN',
  `plays` smallint unsigned NOT NULL DEFAULT '0',
  `listen_sec` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`session_id`),
  UNIQUE KEY `uq_ls_session_user` (`session_id`,`user_id`),
  KEY `idx_ls_user_status` (`user_id`,`status`,`last_activity_at`),
  KEY `fk_ls_ctx` (`context_id`),
  CONSTRAINT `fk_ls_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `chk_ls_state` CHECK ((((`status` = _utf8mb4'OPEN') and (`ended_at` is null)) or ((`status` = _utf8mb4'CLOSED') and (`ended_at` is not null) and (`ended_at` >= `started_at`))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `recommendation_batches` (
  `batch_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `incognito_id` bigint unsigned DEFAULT NULL,
  `model_id` smallint unsigned NOT NULL,
  `strategy` enum('MOOD','TEXT','CONTEXT','DAILY','SIMILAR','TRENDING','DISCOVERY','REGIONAL','WORLD','SMART_PLAYLIST','RECOVERY') NOT NULL,
  `label` varchar(120) DEFAULT NULL,
  `input_text` varchar(280) DEFAULT NULL,
  `context_id` tinyint unsigned DEFAULT NULL,
  `seed_song_id` int unsigned DEFAULT NULL,
  `language_id` smallint unsigned DEFAULT NULL,
  `target_energy` decimal(4,3) NOT NULL,
  `target_valence` decimal(4,3) NOT NULL,
  `target_danceability` decimal(4,3) NOT NULL,
  `target_acousticness` decimal(4,3) NOT NULL,
  `target_instrumentalness` decimal(4,3) NOT NULL,
  `tempo_min` decimal(5,1) NOT NULL,
  `tempo_max` decimal(5,1) NOT NULL,
  `max_speechiness` decimal(4,3) NOT NULL DEFAULT '1.000',
  `discovery_only` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`batch_id`),
  KEY `idx_rb_user_time` (`user_id`,`created_at`),
  KEY `fk_rb_model` (`model_id`),
  KEY `fk_rb_ctx` (`context_id`),
  KEY `fk_rb_seed` (`seed_song_id`),
  KEY `fk_rb_lang` (`language_id`),
  KEY `fk_rb_incognito` (`incognito_id`),
  CONSTRAINT `fk_rb_seed` FOREIGN KEY (`seed_song_id`) REFERENCES `songs` (`song_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_rb_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `chk_rb_targets` CHECK (((`target_energy` between 0 and 1) and (`target_valence` between 0 and 1) and (`target_danceability` between 0 and 1) and (`target_acousticness` between 0 and 1) and (`target_instrumentalness` between 0 and 1) and (`max_speechiness` between 0 and 1))),
  CONSTRAINT `chk_rb_tempo` CHECK ((`tempo_min` < `tempo_max`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `listening_history` (
  `play_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `session_id` bigint unsigned NOT NULL,
  `user_id` int unsigned NOT NULL,
  `song_id` int unsigned NOT NULL,
  `batch_id` bigint unsigned DEFAULT NULL,
  `origin` enum('HOME','MOOD','CONTEXT','WORLD','SEARCH','PLAYLIST','LIBRARY','SMART_PLAYLIST') NOT NULL DEFAULT 'HOME',
  `started_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ended_at` datetime DEFAULT NULL,
  `listened_sec` smallint unsigned NOT NULL DEFAULT '0',
  `completion_pct` decimal(5,2) NOT NULL DEFAULT '0.00',
  `completed` tinyint(1) NOT NULL DEFAULT '0',
  `skipped` tinyint(1) NOT NULL DEFAULT '0',
  `is_replay` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`play_id`),
  KEY `idx_lh_user_time` (`user_id`,`started_at`),
  KEY `idx_lh_user_song` (`user_id`,`song_id`,`started_at`),
  KEY `idx_lh_song_time` (`song_id`,`started_at`),
  KEY `idx_lh_session` (`session_id`),
  KEY `fk_lh_session_user` (`session_id`,`user_id`),
  KEY `fk_lh_batch` (`batch_id`),
  CONSTRAINT `fk_lh_batch` FOREIGN KEY (`batch_id`) REFERENCES `recommendation_batches` (`batch_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_lh_session_user` FOREIGN KEY (`session_id`, `user_id`) REFERENCES `listening_sessions` (`session_id`, `user_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_lh_song` FOREIGN KEY (`song_id`) REFERENCES `songs` (`song_id`) ON DELETE CASCADE,
  CONSTRAINT `chk_lh_end` CHECK (((`ended_at` is null) or (`ended_at` >= `started_at`))),
  CONSTRAINT `chk_lh_flags` CHECK (((`completed` <> 1) or (`skipped` <> 1))),
  CONSTRAINT `chk_lh_pct` CHECK ((`completion_pct` between 0 and 100))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `recommendation_items` (
  `batch_id` bigint unsigned NOT NULL,
  `song_id` int unsigned NOT NULL,
  `rank_position` smallint unsigned NOT NULL,
  `final_score` decimal(6,4) NOT NULL,
  `mood_score` decimal(6,4) DEFAULT NULL,
  `audio_score` decimal(6,4) NOT NULL,
  `preference_score` decimal(6,4) NOT NULL,
  `recency_score` decimal(6,4) DEFAULT NULL,
  `trend_score` decimal(6,4) NOT NULL,
  `context_score` decimal(6,4) DEFAULT NULL,
  `regional_score` decimal(6,4) DEFAULT NULL,
  `exploration_score` decimal(6,4) NOT NULL,
  `repetition_penalty` decimal(6,4) NOT NULL,
  PRIMARY KEY (`batch_id`,`song_id`),
  UNIQUE KEY `uq_ri_rank` (`batch_id`,`rank_position`),
  KEY `idx_ri_song` (`song_id`),
  CONSTRAINT `fk_ri_batch` FOREIGN KEY (`batch_id`) REFERENCES `recommendation_batches` (`batch_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ri_song` FOREIGN KEY (`song_id`) REFERENCES `songs` (`song_id`) ON DELETE CASCADE,
  CONSTRAINT `chk_ri_score` CHECK ((`final_score` between 0 and 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `playlists` (
  `playlist_id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `name` varchar(80) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `kind` enum('MANUAL','SMART','SAVED_MIX','WORLD') NOT NULL DEFAULT 'MANUAL',
  `smart_type` varchar(30) DEFAULT NULL,
  `source_batch_id` bigint unsigned DEFAULT NULL,
  `song_count` smallint unsigned NOT NULL DEFAULT '0',
  `total_duration_sec` int unsigned NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`playlist_id`),
  UNIQUE KEY `uq_playlists_user_name` (`user_id`,`name`),
  KEY `fk_pl_batch` (`source_batch_id`),
  CONSTRAINT `fk_pl_batch` FOREIGN KEY (`source_batch_id`) REFERENCES `recommendation_batches` (`batch_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_pl_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `chk_pl_name` CHECK ((char_length(trim(`name`)) >= 1)),
  CONSTRAINT `chk_pl_smart` CHECK (((`kind` = _utf8mb4'SMART') = (`smart_type` is not null)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `playlist_songs` (
  `playlist_id` int unsigned NOT NULL,
  `song_id` int unsigned NOT NULL,
  `position` smallint unsigned NOT NULL DEFAULT '0',
  `added_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`playlist_id`,`song_id`),
  KEY `idx_ps_song` (`song_id`),
  CONSTRAINT `fk_ps_playlist` FOREIGN KEY (`playlist_id`) REFERENCES `playlists` (`playlist_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ps_song` FOREIGN KEY (`song_id`) REFERENCES `songs` (`song_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Foreign keys left out of this 16-table version (present in the real database):
--   users(role_id) -> roles
--   user_profiles(region_code) -> regions
--   artists(primary_language_id) -> languages
--   artists(region_code) -> regions
--   albums(film_id) -> films
--   albums(language_id) -> languages
--   songs(language_id) -> languages
--   moods(category_id) -> mood_categories
--   song_moods(feature_id) -> audio_features
--   song_moods(model_id) -> intelligence_models
--   listening_sessions(context_id) -> contexts
--   recommendation_batches(context_id) -> contexts
--   recommendation_batches(incognito_id) -> incognito_sessions
--   recommendation_batches(language_id) -> languages
--   recommendation_batches(model_id) -> intelligence_models
